'use strict';

/**
 * Parse a single amount string into a Number, handling:
 *   - en-US format: dot = decimal, comma = thousands  ("$1,234.56")
 *   - de-DE format: comma = decimal, dot = thousands  ("1.234,56")
 *   - leading currency symbols ($, €, £, ¥ …)
 *   - leading sign (+ / -)
 *   - missing / empty / unparseable values → 0
 *
 * Rule: the LAST of '.' / ',' is the decimal separator; the other is a
 * thousands separator.  If only one separator type exists, it is the
 * decimal separator.
 */
function parseAmount(raw) {
  if (typeof raw !== 'string') return 0;

  var s = raw.trim();
  if (s === '') return 0;

  // Extract leading sign.
  var sign = '';
  if (s[0] === '-' || s[0] === '+') {
    sign = s[0];
    s = s.slice(1);
  }

  // Strip currency symbols (anything that is not a digit, comma, dot, or sign).
  s = s.replace(/[^\d.,+-]/g, '');
  if (s === '') return 0;

  // Determine which character is the decimal separator.
  var lastDot = s.lastIndexOf('.');
  var lastComma = s.lastIndexOf(',');

  if (lastDot > -1 && lastComma > -1) {
    if (lastComma > lastDot) {
      // de-DE: comma is decimal, dot is thousands.
      s = s.replace(/\./g, '').replace(',', '.');
    } else {
      // en-US: dot is decimal, comma is thousands.
      s = s.replace(/,/g, '');
    }
  } else if (lastComma > -1) {
    // Only comma → treat as decimal point.
    s = s.replace(',', '.');
  }
  // Only dot (or neither) → dot is already the decimal point; nothing to do.

  var num = Number(sign + s);
  return isNaN(num) ? 0 : num;
}

/**
 * Sum the `amount` field across all rows and return the grand total as a
 * Number rounded to 2 decimal places (half-up via Math.round).
 *
 * Each row: { amount: "<string>", currency: "<string>" }
 *
 * @param {Array<{amount: string}>} rows
 * @returns {number}
 */
function sumAmounts(rows) {
  var total = 0;
  for (var i = 0; i < rows.length; i++) {
    total += parseAmount(rows[i] && rows[i].amount);
  }
  return Math.round(total * 100) / 100;
}

module.exports = { sumAmounts };

